#!/bin/sh
command -v espeak-ng>/dev/null||exit 2;d=$(mktemp -d)||exit 3;d=$(realpath "$d")||exit 3;trap 'rm -rf "$d"' 0;for x in ./*.txt;do [ -f "$x" ]&&echo "$x";done>"$d/F";[ -s "$d/F" ]||exit 4;echo TXT-files:;nl -ba "$d/F";printf 'File# ';read n;f=$(sed -n "$n p" "$d/F");[ -n "$f" ]||exit 5;espeak-ng --voices 2>/dev/null|awk 'NR>1{print $2}'|sort -u>"$d/V";echo TTS-voices:;nl -ba "$d/V";printf 'TTS# ';read n;V=$(sed -n "$n p" "$d/V");b=${f#./};b=${b%.ocr.txt};b=${b%.txt};w=./$b.tts.wav;tr -s '[:space:]' ' '<"$f">"$d/t";espeak-ng -q -x -v "$V" -f "$f">"$d/a";espeak-ng -q -x -v "$V" -f "$d/t">"$d/b";cmp -s "$d/a" "$d/b"&&Z=1||Z=0;tr -s '[:space:]' ' '<"$d/a">"$d/c";tr -s '[:space:]' ' '<"$d/b">"$d/e";cmp -s "$d/c" "$d/e"&&Q=1||Q=0;espeak-ng -v "$V" -s ${RATE:-165} -p ${PITCH:-50} -w "$w" -f "$d/t"||exit 11;h(){ [ "$1" = 1 ]&&echo 0||echo '>0';};echo "WAV=$w TTS=$V H_strict=$(h $Z) H_task=$(h $Q) zero_strict=$([ $Z = 1 ]&&echo true||echo false) zero_task=$([ $Q = 1 ]&&echo true||echo false)"
